	this.instance_1.setTransform(288,21);

	this.instance_2 = new lib.A29();
	this.instance_2.setTransform(109.85,624.3);

	this.mainMenu = new lib.A62();
	this.mainMenu.name = "mainMenu";
	this.mainMenu.setTransform(1170.25,624.4,1,1,0,0,0,0.1,0.1);
	new cjs.ButtonHelper(this.mainMenu, 0, 1, 2, false, new lib.A62(), 3);

